const paths={inbox:'M3 13 6 4h12l3 9v7H3v-7Zm0 0h5l2 3h4l2-3h5M8 8h8',note:'M4 3h16v13l-5 5H4V3Zm11 18v-6h5M8 8h8M8 12h6',calendar:'M4 5h16v16H4V5ZM8 3v4m8-4v4M4 10h16M8 14h2m4 0h2M8 17h2',cloud:'M6 18a5 5 0 0 1-1-9 7 7 0 0 1 13-1 5 5 0 0 1 0 10H6Z',folder:'M3 7V5a1 1 0 0 1 1-1h5l2 3h9a1 1 0 0 1 1 1v11a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V7Z',files:'M5 3h9l5 5v13H5V3Zm9 0v6h5M8 13h8M8 17h6',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8m6 10v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Zm-4 9 3 3 5-6',upload:'M12 16V3m-4 4 4-4 4 4M4 15v5h16v-5',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',plus:'M12 5v14M5 12h14',more:'M5 12h.01M12 12h.01M19 12h.01',chevron:'m9 5 7 7-7 7',down:'M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4',close:'m6 6 12 12M6 18 18 6',lock:'M6 11h12v10H6V11Zm2 0V7a4 4 0 0 1 8 0v4',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',grid:'M3 3h7v7H3V3Zm11 0h7v7h-7V3ZM3 14h7v7H3v-7Zm11 0h7v7h-7v-7Z',logout:'M9 21H3V3h6m7 4 5 5-5 5M8 12h13',menu:'M3 6h18M3 12h18M3 18h18',check:'m5 12 4 4L19 6',mail:'M3 5h18v14H3V5Zm0 1 9 7 9-7',move:'M3 7V4h6l3 3h9v13H3V7Zm4 6h10m-3-3 3 3-3 3',edit:'m15 5 4 4M3 21l5-1L21 7l-5-5L3 15v6Z',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.files}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=name=>name.split(' ').map(n=>n[0]).slice(0,2).join('').toUpperCase();
const users=[],folders=[],files=[];
let currentUser=null,signedIn=false,page='files',currentFolder=null,query='',typeFilter='all',view='list',csrf='',limits={maxFileBytes:100000000};
const $=s=>document.querySelector(s);const user=()=>users.find(u=>u.id===currentUser);const rootFolder=id=>{let f=folders.find(f=>f.id===id);while(f?.parent)f=folders.find(x=>x.id===f.parent);return f};
const permission=id=>folders.find(f=>f.id===id)?.permission||null;
const can=(id,action)=>{const role=permission(id);return action==='view'?!!role:action==='upload'?['Super User','Manager','Contributor'].includes(role):['Super User','Manager'].includes(role)};
async function api(path,options={}){const headers={...options.headers};if(options.method&&options.method!=='GET'){headers['X-CSRF-Token']=csrf;if(options.body!==undefined){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body)}}const response=await fetch('/api'+path,{...options,headers,credentials:'same-origin'});const data=await response.json();if(!response.ok){if(response.status===401&&!path.startsWith('/login')){signedIn=false;$('#modal').close();renderLogin()}const error=new Error(data.error||'Request failed.');error.code=data.code;error.restart=data.restart===true;throw error}return data;}
async function syncWorkspace(){const data=await api('/workspace');users.splice(0,users.length,...data.users);folders.splice(0,folders.length,...data.folders);files.splice(0,files.length,...data.files);currentUser=data.user.id;csrf=data.csrf;limits=data.limits;signedIn=true;inboxUnread=(await api('/inbox/count')).unread;render();}
async function boot(){try{const status=await api('/status');if(status.setupRequired){renderSetup();return}try{const me=await api('/me');csrf=me.csrf;currentUser=me.user.id;users.splice(0,users.length,me.user);if(me.user.mustChangePassword){renderPasswordPage();return}await syncWorkspace()}catch{signedIn=false;renderLogin()}}catch{$('#app').innerHTML='<main class="login-panel" style="min-height:100vh"><div><h1>Unable to connect</h1><p>Please refresh once the server is available.</p></div></main>'}}
const formatSize=n=>n>=1e6?`${(n/1e6).toFixed(1)} MB`:n>=1000?`${Math.round(n/1000)} KB`:`${n} B`;
const avatar=id=>{const u=users.find(x=>x.id===id);return `<span class="avatar" title="${esc(u?.name||'User')}">${esc(initials(u?.name||'User'))}</span>`};
const badge=f=>`<span class="file-badge ${esc(f.ext)}">${icon('files')}<small>${esc(f.ext.toUpperCase().slice(0,4))}</small></span>`;
const brand=()=>`<div class="brand company-brand"><img class="company-logo" src="/irish-hospital-supplies-logo.png" alt="Irish Hospital Supplies" width="1200" height="437"><div class="cloud-brand-label">IHS <span>Irish Hospital Supplies Cloud</span></div></div>`;
const btn=(label,action,ic,primary=false)=>`<button type="button" class="btn ${primary?'primary':''}" data-action="${action}">${icon(ic)}${label}</button>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function visibleFiles(){return files.filter(f=>can(f.folder,'view')&&(!currentFolder||f.folder===currentFolder)&&(page!=='shared'||Object.keys(rootFolder(f.folder)?.grants||{}).length>0)&&f.name.toLowerCase().includes(query.toLowerCase())&&(typeFilter==='all'||(typeFilter==='documents'?['pdf','doc','docx','txt'].includes(f.ext):typeFilter==='images'?['png','jpg','jpeg','webp','gif','svg'].includes(f.ext):typeFilter==='spreadsheets'?['xlsx','xls','csv'].includes(f.ext):!['pdf','doc','docx','txt','png','jpg','jpeg','webp','gif','svg','xlsx','xls','csv'].includes(f.ext))));}
function render(){if(!signedIn){renderLogin();return}$('#app').innerHTML=`<button class="mobile-scrim" data-action="menu" aria-label="Close navigation"></button><aside class="sidebar">${brand()}<div class="nav-label">Workspace</div><nav aria-label="Main navigation"><button class="nav-button ${page==='files'?'active':''}" data-action="nav-files">${icon('folder')}My files<span class="count">${files.filter(f=>can(f.folder,'view')).length}</span></button><button class="nav-button ${page==='shared'?'active':''}" data-action="nav-shared">${icon('users')}Shared with me</button><button class="nav-button ${page==='board'?'active':''}" data-action="nav-board">${icon('note')}Message Board</button><button class="nav-button ${page==='inbox'?'active':''}" data-action="nav-inbox">${icon('inbox')}In-tray<span class="count inbox-count" ${inboxUnread?'':'hidden'}>${inboxUnread}</span></button><button class="nav-button ${page==='calendar'?'active':''}" data-action="nav-calendar">${icon('calendar')}Calendar diary</button>${user().role==='Super User'?`<div class="nav-label">Administration</div><button class="nav-button ${page==='users'?'active':''}" data-action="nav-users">${icon('users')}User management</button><button class="nav-button ${page==='groups'?'active':''}" data-action="nav-groups">${icon('users')}User groups</button>`:''}</nav><div class="sidebar-bottom"><div class="profile">${avatar(currentUser)}<div><strong>${esc(user().name)}</strong><small>${esc(user().role)}</small></div><button data-action="logout" title="Sign out" aria-label="Sign out">${icon('logout')}</button></div></div></aside><div class="shell"><header class="topbar"><div class="top-label"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button>${icon('cloud')}<span>Irish Hospital Supplies Cloud</span></div><div class="top-actions"><button class="btn" data-action="devices">Desktop sync</button><button class="btn" data-action="change-password">Account</button></div></header><main class="content" id="main">${page==='board'?renderBoard():page==='inbox'?renderInbox():page==='groups'?renderGroups():page==='calendar'?renderCalendar():page==='users'?renderUsers():renderWorkspace()}</main></div>`;bind();}
let workspaceTab='folders';
function renderWorkspace(){const f=folders.find(f=>f.id===currentFolder);if(currentFolder&&!can(currentFolder,'view'))return '<div class="empty"><h1>Access restricted</h1><button class="btn" data-action="nav-files">My files</button></div>';const uploadable=currentFolder?can(currentFolder,'upload'):folders.some(f=>can(f.id,'upload')),createable=currentFolder?can(currentFolder,'upload'):user().role==='Super User';const children=folders.filter(f=>f.parent===currentFolder&&can(f.id,'view')&&(page!=='shared'||Object.keys(rootFolder(f.id)?.grants||{}).length));const showFiles=!!currentFolder||workspaceTab==='recent';return `${uploadable?`<div class="drop-zone upload-top" id="drop-zone">${icon('upload')}<strong>Drop files or <button class="text-button" data-action="upload">browse</button></strong><span>${formatSize(limits.maxFileBytes)} max</span></div>`:''}<div class="page-heading"><h1>${esc(f?.name||(page==='shared'?'Shared with me':'My files'))}</h1><div class="actions">${createable?btn('New folder','new-folder','plus'):''}${uploadable?btn('Upload files','upload','upload',true)+btn('Add file location','add-location','plus'):''}${f&&can(f.id,'manage')?btn('Share folder',`share:${f.id}`,'users'):''}</div></div>${currentFolder?breadcrumbs():`<div class="workspace-tabs" role="tablist" aria-label="File views"><button role="tab" aria-selected="${workspaceTab==='folders'}" data-action="workspace-folders">Folders</button><button role="tab" aria-selected="${workspaceTab==='recent'}" data-action="workspace-recent">Recent</button></div>`}${workspaceTab==='folders'||currentFolder?`<section aria-label="Folders"><div class="folder-grid">${children.map(f=>`<article class="folder-card"><div class="folder-top"><span class="folder-icon">${icon('folder')}</span>${can(f.id,'manage')?`<button class="icon-button" data-action="folder-menu:${f.id}" aria-label="Manage ${esc(f.name)}">${icon('more')}</button>`:''}</div><button class="folder-open" data-action="open-folder:${f.id}">${esc(f.name)}</button><div class="folder-meta">${files.filter(x=>x.folder===f.id).length} files</div></article>`).join('')}</div>${!children.length&&!currentFolder?'<p class="muted">No folders.</p>':''}</section>`:''}${showFiles?`<section class="files-panel compact-files" aria-label="${currentFolder?'Folder files':'Recent files'}"><div class="files-toolbar"><h2>${currentFolder?'Files':'Recent'}</h2><label class="search">${icon('search')}<input id="search" type="search" aria-label="Search files" placeholder="Search" value="${esc(query)}"></label></div><div id="file-results">${renderFiles()}</div><div class="table-footer"><span id="results-label">${visibleFiles().length} files</span></div></section>`:''}`;}

function breadcrumbs(){let chain=[],f=folders.find(f=>f.id===currentFolder);while(f){chain.unshift(f);f=folders.find(x=>x.id===f.parent)}return `<nav class="breadcrumbs" aria-label="Folder path"><button data-action="nav-files">My files</button>${chain.map(f=>`${icon('chevron')}<button data-action="open-folder:${f.id}" ${f.id===currentFolder?'aria-current="page"':''}>${esc(f.name)}</button>`).join('')}</nav>`}
function renderFiles(){const list=visibleFiles();if(!list.length)return `<div class="empty">${icon(query?'search':'folder')}<h3>${query||typeFilter!=='all'?'No matching files':'No files'}</h3><p>${query||typeFilter!=='all'?'Try another search or file type.':''}</p></div>`;if(view==='grid')return `<div class="grid-files">${list.map(f=>`<article class="grid-file">${badge(f)}<button class="file-name" data-action="file:${f.id}">${esc(f.name)}</button><div class="file-sub">${f.reference?'Reference':formatSize(f.size)} · ${esc(f.ext.toUpperCase())}</div><div class="actions">${avatar(f.owner)}<button class="icon-button" data-action="file:${f.id}" aria-label="Details for ${esc(f.name)}">${icon('more')}</button></div></article>`).join('')}</div>`;return `<div class="table-scroll"><table><thead><tr><th>Name</th><th class="optional-col">Owner</th><th>Last modified</th><th>Size</th><th>Access</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${list.map(f=>`<tr><td><div class="file-cell">${badge(f)}<div><button class="file-name" title="${esc(f.name)}" data-action="file:${f.id}">${esc(f.name)}</button><div class="file-sub">${esc(folders.find(x=>x.id===f.folder)?.name||'My files')} · ${f.source==='occ'?'IHS Sync':f.source==='existing'?'Existing file':'Host'}</div></div></div></td><td class="optional-col"><span class="owner-cell">${avatar(f.owner)}${f.owner===currentUser?'You':esc(users.find(u=>u.id===f.owner)?.name.split(' ')[0]||'User')}</span></td><td>${isoDate(f.modified)}</td><td>${f.reference?'Reference':formatSize(f.size)}</td><td><span class="pill ${Object.keys(rootFolder(f.folder)?.grants||{}).length?'':'private'}">${icon(Object.keys(rootFolder(f.folder)?.grants||{}).length?'users':'lock')}${Object.keys(rootFolder(f.folder)?.grants||{}).length?'Shared':'Private'}</span></td><td><button class="icon-button" data-action="file:${f.id}" aria-label="Details for ${esc(f.name)}">${icon('more')}</button></td></tr>`).join('')}</tbody></table></div>`}
function updateFiles(){$('#file-results').innerHTML=renderFiles();$('#results-label').textContent=`${visibleFiles().length} files`;}
function renderUsers(){return `<div class="page-heading"><div><div class="eyebrow">Administration</div><h1>User management</h1><p></p></div>${btn('Create user','create-user','plus',true)}</div><div class="notice users-intro">Accounts are created by a Super User. Folder permissions control what each person can access.</div><section class="files-panel"><div class="files-toolbar"><h2>Your team</h2><span class="small muted">${users.filter(u=>u.active).length} active accounts</span></div><div class="table-scroll"><table><thead><tr><th>Name</th><th>Email</th><th>Account</th><th>Status</th><th>Actions</th></tr></thead><tbody>${users.map(u=>`<tr><td><div class="owner-cell">${avatar(u.id)}<strong>${esc(u.name)}</strong></div></td><td>${esc(u.email)}</td><td>${u.role==='Super User'?'Super User':'Standard user'}</td><td><span class="pill ${u.active?'':'private'}">${u.active?'Active':'Inactive'}</span><div class="small ${u.mfaEnabled?'muted':'mfa-off'}">${u.mfaEnabled?'Authenticator set up':'Authenticator not set up'}</div></td><td><button class="btn" data-action="edit-user:${u.id}">Edit</button></td></tr>`).join('')}</tbody></table></div></section><div class="permission-key"><article><h3>Viewer</h3><p>View and download files in assigned folders.</p></article><article><h3>Contributor</h3><p>View, download, upload files, and create subfolders.</p></article><article><h3>Manager</h3><p>Contributor access plus organising, deleting, and sharing within assigned folders.</p></article></div>`}
function loginShell(content){$('#app').innerHTML=`<main class="login"><section class="login-art">${brand()}<div><div class="eyebrow">Irish Hospital Supplies Cloud</div><h1>Irish Hospital Supplies Cloud</h1><p></p></div><small>IHS Cloud · Irish Hospital Supplies</small></section><section class="login-panel">${content}</section></main>`;}
function renderLogin(){loginShell(`<form class="login-form" id="login-form"><h2>Welcome back</h2><p>Sign in to your Irish Hospital Supplies workspace.</p><label class="field">Email address<input type="email" name="email" required autocomplete="username"></label><label class="field">Password<input type="password" name="password" required autocomplete="current-password"></label><div id="login-error" class="error" role="alert"></div><button class="btn primary" type="submit">Sign in</button><p class="small muted" style="margin-top:20px">Need an account or a password reset? Contact your Super User.</p></form>`);$('#login-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type=submit]');button.disabled=true;try{const data=new FormData(e.target);const result=await api('/login',{method:'POST',body:Object.fromEntries(data)});if(result.step==='none')await finishSignIn(result);else renderCodeStep(result)}catch(err){$('#login-error').textContent=err.message}finally{button.disabled=false}};}
async function finishSignIn(result){csrf=result.csrf;currentUser=result.user.id;users.splice(0,users.length,result.user);page='files';currentFolder=null;query='';if(result.user.mustChangePassword){renderPasswordPage();return}await syncWorkspace()}
// Second sign-in step: the authenticator code, or setting the authenticator up on first sign-in.
function renderCodeStep(step){const setup=step.step==='totp_setup';loginShell(`<form class="login-form code-step" id="code-form"><h2>${setup?'Set up your authenticator':'Enter your code'}</h2>${setup?`<p>Install an authenticator app on your phone (Google Authenticator, Microsoft Authenticator or 1Password), add an account and scan this code.</p><div class="setup-qr">${step.qrSvg}</div><p class="small">Can’t scan? On this phone, <a href="${esc(step.otpauthUrl)}">open it in your authenticator app</a>, or type this key:</p><code class="setup-key">${esc(step.key)}</code><p>Then enter the 6-digit code the app shows.</p>`:'<p>Open your authenticator app and enter the 6-digit code for Irish Hospital Supplies Cloud. Lost your phone? Enter one of your recovery codes instead.</p>'}<label class="field">Code<input name="code" class="code-input" required maxlength="20" autocomplete="one-time-code" ${setup?'inputmode="numeric"':''}></label><div id="code-error" class="error" role="alert"></div><button class="btn primary" type="submit">${setup?'Turn on and sign in':'Sign in'}</button><button class="btn" type="button" id="code-back">Start again</button></form>`);$('#code-form [name=code]').focus();$('#code-back').onclick=()=>renderLogin();
$('#code-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]'),input=e.target.code;button.disabled=true;try{const result=await api('/login/verify',{method:'POST',body:{code:input.value}});if(result.recoveryCodes)return renderRecoveryCodes(result);await finishSignIn(result);if(result.recoveryCodesLeft!==undefined)toast(`Recovery code used. ${result.recoveryCodesLeft} left.`)}catch(err){if(err.restart){renderLogin();$('#login-error').textContent=err.message;return}$('#code-error').textContent=err.message;input.value='';input.focus()}finally{button.disabled=false}};}
function renderRecoveryCodes(result){const codes=result.recoveryCodes;loginShell(`<div class="login-form code-step"><h2>Save your recovery codes</h2><p>If you lose your phone, each code lets you sign in once instead of the authenticator code. Keep them somewhere safe; they won’t be shown again.</p><ol class="recovery-codes">${codes.map(c=>`<li><code>${esc(c)}</code></li>`).join('')}</ol><div class="code-actions"><button class="btn" type="button" id="copy-codes">Copy codes</button><button class="btn" type="button" id="print-codes">Print</button></div><label class="check-label"><input type="checkbox" id="codes-saved"> I have saved these codes</label><button class="btn primary" type="button" id="codes-continue" disabled>Continue</button></div>`);
$('#copy-codes').onclick=async()=>{try{await navigator.clipboard.writeText(codes.join('\n'));toast('Recovery codes copied')}catch{toast('Copy failed. Write the codes down or print them.')}};$('#print-codes').onclick=()=>{document.body.classList.add('printing-recovery');window.print();document.body.classList.remove('printing-recovery')};$('#codes-saved').onchange=e=>{$('#codes-continue').disabled=!e.target.checked};$('#codes-continue').onclick=()=>finishSignIn(result);}
function renderSetup(){loginShell(`<form class="login-form" id="setup-form"><h2>Set up your workspace</h2><p>Create the first Super User. The setup key is supplied by your server administrator.</p><label class="field">Setup key<input name="token" type="password" required autocomplete="off"></label><label class="field">Full name<input name="name" required maxlength="80" autocomplete="name"></label><label class="field">Email address<input name="email" type="email" required autocomplete="username"></label><label class="field">Password<input name="password" type="password" required minlength="15" maxlength="128" autocomplete="new-password"><small>Use at least 15 characters.</small></label><label class="field">Confirm password<input name="confirm" type="password" required autocomplete="new-password"></label><div id="setup-error" class="error" role="alert"></div><button class="btn primary" type="submit">Create Super User</button></form>`);$('#setup-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));if(data.password!==data.confirm)throw Error('Passwords do not match.');await api('/setup',{method:'POST',body:data});renderLogin();toast('Workspace ready. Sign in with your new account.')}catch(err){$('#setup-error').textContent=err.message}finally{button.disabled=false}};}
function passwordFields(){return '<label class="field">Current password<input name="currentPassword" type="password" required autocomplete="current-password"></label><label class="field">New password<input name="password" type="password" required minlength="15" maxlength="128" autocomplete="new-password"><small>Use at least 15 characters.</small></label><label class="field">Confirm new password<input name="confirm" type="password" required autocomplete="new-password"></label>';}
async function savePassword(data){const payload=Object.fromEntries(data);if(payload.password!==payload.confirm)throw Error('Passwords do not match.');await api('/password',{method:'POST',body:payload});signedIn=false;csrf='';$('#modal').close();renderLogin();toast('Password changed. Sign in with your new password.');}
function renderPasswordPage(){signedIn=false;loginShell(`<form class="login-form" id="password-form"><h2>Choose your password</h2><p>Replace your temporary password before opening the workspace.</p>${passwordFields()}<div id="password-error" class="error" role="alert"></div><button class="btn primary" type="submit">Save password</button><button class="btn" type="button" id="password-signout" style="margin-top:12px">Sign out</button></form>`);$('#password-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('[type=submit]');b.disabled=true;try{await savePassword(new FormData(e.target))}catch(err){$('#password-error').textContent=err.message}finally{b.disabled=false}};$('#password-signout').onclick=async()=>{await api('/logout',{method:'POST'});renderLogin()};}
function bind(){if($('#search'))$('#search').oninput=e=>{query=e.target.value;updateFiles()};if($('#type-filter'))$('#type-filter').onchange=e=>{typeFilter=e.target.value;updateFiles()};const drop=$('#drop-zone');if(drop){drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');startUpload([...e.dataTransfer.files])}}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const [action,id]=b.dataset.action.split(':');Promise.resolve(handleAction(action,id)).catch(error=>toast(error.message))});
async function handleAction(action,id){if(action==='nav-board'){await loadBoard();page='board';render();return;}if(action==='nav-inbox'){await loadInbox();page='inbox';render();return;}if(action.startsWith('board-'))return boardAction(action,id);if(action.startsWith('inbox-'))return inboxAction(action,id);if(action==='add-location')return addLocation();if(action==='edit-reference')return referenceForm(files.find(f=>f.id===id));if(action==='delete-reference')return deleteReference(id);if(action==='copy-path'){const f=files.find(f=>f.id===id);if(f?.reference){await navigator.clipboard.writeText(f.path);toast('Path copied');}return;}if(action==='notify-file')return notifyFile(id);if(action.startsWith('workspace-')){workspaceTab=action.slice(10);query='';view='list';render();return;}if(action.startsWith('group-'))return groupAction(action,id);if(action.startsWith('cal-'))return calendarAction(action,id);if(action==='menu'){$('.sidebar')?.classList.toggle('open');$('.mobile-scrim')?.classList.toggle('open');return}if(action==='logout'){await api('/logout',{method:'POST'});signedIn=false;csrf='';workspaceTab='folders';diaryBookings=[];userGroups=[];boardNotes=[];inboxItems=[];inboxUnread=0;render();return}if(action==='devices')return showDevices();if(action==='new-device')return newDevice();if(action==='revoke-device')return revokeDevice(id);if(action==='change-password'){openModal('Change password',passwordFields(),modalButtons('Save password'),savePassword);return}if(action==='nav-groups'){await loadGroups();page='groups';render();return;}if(action==='nav-calendar'){await loadCalendar();page='calendar';render();return}if(action.startsWith('nav-')){page=action.slice(4);currentFolder=null;query='';typeFilter='all';if(page==='users'&&user().role!=='Super User')page='files';render();return}if(action==='open-folder'){currentFolder=id;query='';render();return}if(action.startsWith('view-')){view=action.slice(5);render();return}if(action==='close'){$('#modal').close();return}if(!signedIn||!user()?.active)return;if(action==='new-folder')return newFolder();if(action==='upload')return chooseUpload();if(action==='share')return shareFolder(id);if(action==='file')return fileDetails(id);if(action==='folder-menu')return folderMenu(id);if(action==='create-user')return editUser();if(action==='edit-user')return editUser(id);if(action==='reset-mfa')return resetAuthenticator(id);if(action==='rename-file')return renameItem(id,false);if(action==='rename-folder')return renameItem(id,true);if(action==='move-file')return moveItem(id,false);if(action==='move-folder')return moveItem(id,true);if(action==='delete-file')return deleteItem(id,false);if(action==='delete-folder')return deleteItem(id,true);if(action==='download')return downloadFile(id);}
let lastFocus=null,uploadTarget=null,uploading=false;
function openModal(title,body,footer='',onSubmit=null){const modal=$('#modal');if(!modal.open)lastFocus=document.activeElement;modal.innerHTML=`<form id="modal-form"><header class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button type="button" class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></header><div class="modal-body">${body}<div class="error" id="modal-error" role="alert"></div></div><footer class="modal-footer">${footer||'<button type="button" class="btn" data-action="close">Done</button>'}</footer></form>`;modal.setAttribute('aria-labelledby','modal-title');$('#modal-form').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('[type=submit]');if(submit)submit.disabled=true;try{await onSubmit?.(new FormData(e.target))}catch(err){if($('#modal-error'))$('#modal-error').textContent=err.message}finally{if(submit)submit.disabled=false}};if(!modal.open)modal.showModal();setTimeout(()=>modal.querySelector('input,select,button')?.focus(),0);}
$('#modal').addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus();else $('#main h1')?.focus()});
const modalButtons=(label='Save changes',danger=false)=>`<button type="button" class="btn" data-action="close">Cancel</button><button type="submit" class="btn ${danger?'danger':'primary'}">${label}</button>`;
const uid=prefix=>`${prefix}-${crypto.randomUUID()}`;
function validName(name){const n=String(name||'').trim();if(!n||n==='.'||n==='..'||/[\\/\x00-\x1f]/.test(n))throw Error('Enter a name without slashes or control characters.');if(n.length>160)throw Error('Use a name of 160 characters or fewer.');return n;}
function duplicate(name,container,folder,except){return(folder?folders:files).some(x=>x.id!==except&&(folder?x.parent:x.folder)===container&&x.name.toLowerCase()===name.toLowerCase());}
async function createFolder(name,parent=currentFolder){if(parent?!can(parent,'upload'):user().role!=='Super User')throw Error('You do not have permission to create a folder here.');name=validName(name);const result=await api('/folders',{method:'POST',body:{name,parent}});await syncWorkspace();return {id:result.id,name};}
function newFolder(){if(currentFolder?!can(currentFolder,'upload'):user().role!=='Super User')return toast('You do not have permission to create a folder here.');openModal('Create a folder',`<label class="field">Folder name<input name="name" placeholder="e.g. Service documentation" maxlength="160" required autofocus></label><p>${currentFolder?'This folder will inherit access from '+esc(rootFolder(currentFolder).name)+'.':'New top-level folders start private. Use Share folder to give your team access.'}</p>`,modalButtons('Create folder'),async data=>{const f=await createFolder(data.get('name'));$('#modal').close();toast(`“${f.name}” created`)});}
function folderMenu(id){const f=folders.find(x=>x.id===id);if(!f||!can(id,'manage'))return toast('You do not have permission to manage this folder.');openModal(f.name,`<p style="margin-bottom:15px">Manage this folder and everything inside it.</p><div style="display:grid;gap:10px">${btn('Manage sharing',`share:${id}`,'users')}${btn('Rename folder',`rename-folder:${id}`,'edit')}${btn('Move folder',`move-folder:${id}`,'move')}${btn('Delete folder',`delete-folder:${id}`,'trash')}</div>`);}
function shareFolder(id){const f=folders.find(x=>x.id===id);if(!f||!can(id,'manage'))return toast('You do not have permission to share this folder.');const root=rootFolder(id);const others=users.filter(u=>u.role!=='Super User'&&u.active);openModal('Manage folder access',`<div class="notice">${root.id!==id?`“${esc(f.name)}” inherits access from <strong>${esc(root.name)}</strong>. Changes here apply to that entire parent folder and its contents.`:`Access to <strong>${esc(root.name)}</strong> applies to all its files and subfolders.`}</div><p class="role-help">Viewer: view & download · Contributor: also upload & create folders · Manager: also organise, delete & share.</p>${users.filter(u=>u.role==='Super User'&&u.active).map(u=>`<div class="sharing-row">${avatar(u.id)}<div><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></div><span class="status">Super User</span></div>`).join('')}${others.map(u=>`<div class="sharing-row">${avatar(u.id)}<div><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></div><select name="grant-${u.id}" aria-label="Access for ${esc(u.name)}">${['No access','Viewer','Contributor','Manager'].map(role=>`<option value="${role}" ${(root.grants[u.id]||'No access')===role?'selected':''}>${role}</option>`).join('')}</select></div>`).join('')}${!others.length?'<p>No standard users yet. Create users in User management.</p>':''}`,modalButtons('Save access'),async data=>{const grants={};for(const u of others){const role=data.get('grant-'+u.id);if(rolesForUi.includes(role))grants[u.id]=role;}await api('/folders/'+root.id+'/grants',{method:'PUT',body:{grants}});$('#modal').close();await syncWorkspace();toast('Folder access updated');});}
const rolesForUi=['Viewer','Contributor','Manager'];
function fileDetails(id){const f=files.find(x=>x.id===id);if(f?.reference)return referenceDetails(f);if(!f||!can(f.folder,'view'))return toast('This file is unavailable or you do not have access.');const safeImage=f.url&&['image/png','image/jpeg','image/gif','image/webp'].includes(f.mime);const preview=safeImage?`<img src="${esc(f.url)}" alt="${esc(f.name)}">`:f.url&&f.mime==='application/pdf'?`<iframe src="${esc(f.url)}" title="Preview of ${esc(f.name)}" sandbox></iframe>`:badge(f);openModal(f.name,`<div class="detail-preview">${preview}</div>${!safeImage&&f.mime!=='application/pdf'?'<div class="notice">Download this file to open it with a compatible application.</div>':''}<dl class="details"><dt>Location</dt><dd>Host storage</dd><dt>IHS Cloud path</dt><dd>${esc(folderPath(f.folder))} / ${esc(f.name)}</dd><dt>File type</dt><dd>${esc(f.ext.toUpperCase()||'FILE')}</dd><dt>Size</dt><dd>${f.reference?'Reference':formatSize(f.size)}</dd><dt>Folder</dt><dd>${esc(folders.find(x=>x.id===f.folder)?.name)}</dd><dt>Uploaded by</dt><dd>${esc(users.find(u=>u.id===f.owner)?.name)}</dd><dt>Your access</dt><dd>${esc(permission(f.folder))} · inherited from folder</dd></dl>${can(f.folder,'manage')?`<div class="actions" style="margin-top:24px;flex-wrap:wrap">${btn('Rename',`rename-file:${id}`,'edit')}${btn('Move',`move-file:${id}`,'move')}${btn('Delete',`delete-file:${id}`,'trash')}${btn('Folder access',`share:${f.folder}`,'users')}</div>`:''}`,`<button class="btn" type="button" data-action="close">Close</button><button class="btn primary" type="button" data-action="download:${id}">${icon('down')}Download file</button>${btn('Notify someone',`notify-file:${id}`,'inbox')}`);}
function downloadFile(id){const f=files.find(x=>x.id===id);if(!f||!can(f.folder,'view'))return toast('You do not have permission to download this file.');const a=document.createElement('a');a.href='/api/files/'+id+'/content';a.download=f.name;a.click();toast('Download requested');}
function renameItem(id,isFolder){const item=(isFolder?folders:files).find(x=>x.id===id);if(!item||!can(isFolder?id:item.folder,'manage'))return toast('You do not have permission to rename this item.');openModal(`Rename ${isFolder?'folder':'file'}`,`<label class="field">Name<input name="name" value="${esc(item.name)}" maxlength="160" required></label>`,modalButtons('Rename'),async data=>{await api('/'+(isFolder?'folders':'files')+'/'+id,{method:'PATCH',body:{name:validName(data.get('name'))}});$('#modal').close();await syncWorkspace();toast('Name updated');});}
function descendants(id){const result=[id];for(let i=0;i<result.length;i++)for(const f of folders)if(f.parent===result[i])result.push(f.id);return result;}
function moveItem(id,isFolder){const item=(isFolder?folders:files).find(x=>x.id===id);if(!item||!can(isFolder?id:item.folder,'manage'))return toast('You do not have permission to move this item.');const excluded=isFolder?descendants(id):[];const candidates=folders.filter(f=>can(f.id,'upload')&&!excluded.includes(f.id)&&(isFolder?item.parent!==f.id:item.folder!==f.id));const allowRoot=isFolder&&user().role==='Super User'&&item.parent!==null;openModal(`Move ${isFolder?'folder':'file'}`,`<p style="margin-bottom:18px">Choose a destination for <strong>${esc(item.name)}</strong>. This item will inherit the destination folder’s access.</p><label class="field">Destination<select name="destination" required><option value="" disabled selected>Select a folder</option>${allowRoot?'<option value="__root">My files (top level)</option>':''}${candidates.map(f=>`<option value="${f.id}">${esc(folderPath(f.id))}</option>`).join('')}</select></label>${!candidates.length&&!allowRoot?'<p>No other folders are available with upload access.</p>':''}`,modalButtons('Move here'),async data=>{const dest=data.get('destination');if(!dest)throw Error('Select a destination.');const target=dest==='__root'?null:dest;await api('/'+(isFolder?'folders':'files')+'/'+id,{method:'PATCH',body:isFolder?{parent:target}:{folder:target}});$('#modal').close();await syncWorkspace();toast('Item moved. Destination access now applies.');});}
function folderPath(id){let f=folders.find(x=>x.id===id),names=[];while(f){names.unshift(f.name);f=folders.find(x=>x.id===f.parent)}return names.join(' / ');}
function deleteItem(id,isFolder){const item=(isFolder?folders:files).find(x=>x.id===id);if(!item||!can(isFolder?id:item.folder,'manage'))return toast('You do not have permission to delete this item.');const ids=isFolder?descendants(id):[];const count=isFolder?files.filter(f=>ids.includes(f.folder)).length:1;openModal(`Delete ${isFolder?'folder':'file'}?`,`<p>Permanently delete <strong>${esc(item.name)}</strong>${isFolder?`, including ${ids.length-1} subfolders and ${count} files`:''}?</p><p style="margin-top:12px">This cannot be undone.</p>`,modalButtons('Delete',true),async()=>{await api('/'+(isFolder?'folders':'files')+'/'+id,{method:'DELETE'});if(ids.includes(currentFolder))currentFolder=item.parent;$('#modal').close();await syncWorkspace();toast(`${isFolder?'Folder':'File'} deleted`);});}
function editUser(id){if(user().role!=='Super User')return toast('Only a Super User can manage accounts.');const u=users.find(x=>x.id===id),roots=folders.filter(f=>!f.parent);openModal(u?'Edit user':'Create user',`<label class="field">Full name<input name="name" value="${esc(u?.name||'')}" required maxlength="80"></label><label class="field">Email address<input name="email" type="email" value="${esc(u?.email||'')}" required></label><label class="field">Account type<select name="account"><option value="standard" ${u?.role!=='Super User'?'selected':''}>Standard user</option><option value="super" ${u?.role==='Super User'?'selected':''}>Super User — full workspace access</option></select></label>${u?`<label class="field">Status<select name="status"><option value="active" ${u.active?'selected':''}>Active</option><option value="inactive" ${!u.active?'selected':''}>Inactive</option></select></label>`:''}<label class="field">${u?'Reset password (optional)':'Temporary password'}<input name="password" type="password" ${u?'':'required'} minlength="15" maxlength="128" autocomplete="new-password"><small>${u?'Leave blank to keep the current password. ':''}Share privately with the user. They must change it at their next sign-in.</small></label>${u&&u.id!==currentUser&&u.mfaEnabled?`<div class="sharing-row"><span>Authenticator set up. Lost phone?</span><button class="btn" type="button" data-action="reset-mfa:${u.id}">Reset authenticator</button></div>`:''}<h3 style="margin:20px 0 10px">Folder access</h3><p class="role-help">Standard users only. Super Users automatically have full access.</p>${roots.map(f=>`<div class="sharing-row"><strong>${esc(f.name)}</strong><select name="folder-${f.id}" aria-label="Access to ${esc(f.name)}">${['No access','Viewer','Contributor','Manager'].map(r=>`<option ${(u&&f.grants[u.id]||'No access')===r?'selected':''}>${r}</option>`).join('')}</select></div>`).join('')}<p style="margin-top:18px">Account invitations are shared manually. No email is sent.</p>`,modalButtons(u?'Save user':'Create user'),async data=>{const grants={};for(const f of roots){const r=data.get('folder-'+f.id);if(rolesForUi.includes(r))grants[f.id]=r;}await api('/users'+(u?'/'+id:''),{method:u?'PATCH':'POST',body:{name:data.get('name'),email:data.get('email'),account:data.get('account'),active:data.get('status')!=='inactive',password:data.get('password'),grants}});$('#modal').close();await syncWorkspace();toast(u?'User updated':'User created');});}
function resetAuthenticator(id){const u=users.find(x=>x.id===id);openModal('Reset authenticator?',`<p>${esc(u.name)} will be signed out and set up a new authenticator at their next sign-in. Their recovery codes stop working.</p>`,modalButtons('Reset authenticator',true),async()=>{await api(`/users/${id}/mfa`,{method:'DELETE'});$('#modal').close();await syncWorkspace();toast('Authenticator reset')});}
function writableFolders(){return folders.filter(f=>can(f.id,'upload'));}
function chooseUpload(){if(uploading)return toast('An upload is already in progress.');if(currentFolder){if(!can(currentFolder,'upload'))return toast('You do not have upload access here.');uploadTarget=currentFolder;$('#file-input').click();return}const options=writableFolders();if(!options.length)return toast('Create a folder or ask your Super User for upload access.');openModal('Choose an upload folder',`<p style="margin-bottom:18px">Files inherit the access of the folder you upload to.</p><label class="field">Upload to<select name="destination">${options.map(f=>`<option value="${f.id}">${esc(folderPath(f.id))}</option>`).join('')}</select></label>`,modalButtons('Choose files'),data=>{uploadTarget=data.get('destination');if(!can(uploadTarget,'upload'))throw Error('You do not have upload access to this folder.');$('#modal').close();$('#file-input').click();});}
$('#file-input').onchange=e=>{const picked=[...e.target.files];e.target.value='';if(picked.length)startUpload(picked,uploadTarget)};
function uploadOne(file,target,onProgress){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/files?folder='+encodeURIComponent(target)+'&name='+encodeURIComponent(file.name));xhr.setRequestHeader('X-CSRF-Token',csrf);xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.timeout=300000;xhr.upload.onprogress=e=>onProgress(e.lengthComputable?Math.round(e.loaded/e.total*100):0);xhr.onload=()=>{let data;try{data=JSON.parse(xhr.responseText)}catch{reject(Error('Upload failed. Please retry.'));return}if(xhr.status>=200&&xhr.status<300)resolve(data);else reject(Error(data.error||'Upload failed.'))};xhr.onerror=()=>reject(Error('Connection interrupted. Please retry.'));xhr.ontimeout=()=>reject(Error('Upload timed out. Please retry.'));xhr.send(file);});}
function startUpload(picked,target=currentFolder){if(!picked.length)return;if(uploading)return toast('An upload is already in progress.');if(!target){const choices=writableFolders();if(!choices.length)return toast('You do not have a folder with upload access.');openModal('Choose an upload folder',`<p style="margin-bottom:18px">${picked.length} file${picked.length===1?'':'s'} ready to add.</p><label class="field">Upload to<select name="destination">${choices.map(f=>`<option value="${f.id}">${esc(folderPath(f.id))}</option>`).join('')}</select></label>`,modalButtons('Upload files'),data=>startUpload(picked,data.get('destination')));return}if(!can(target,'upload'))return toast('You do not have upload access to this folder.');uploading=true;openModal('Uploading files',`<p>Files are saved to <strong>${esc(folderPath(target))}</strong>.</p><div id="upload-list">${picked.map((f,i)=>`<div class="upload-item" id="up-${i}"><header><span>${esc(f.name)}</span><span>${f.reference?'Reference':formatSize(f.size)}</span></header><div class="progress"><span style="width:0%"></span></div><div class="upload-status">Waiting…</div></div>`).join('')}</div>`,'<button type="button" class="btn" data-action="close">Close</button>');(async()=>{let added=0;const uploaded=[];for(let i=0;i<picked.length;i++){const f=picked[i];try{validName(f.name);if(f.size>limits.maxFileBytes)throw Error('Exceeds the '+formatSize(limits.maxFileBytes)+' upload limit.');const saved=await uploadOne(f,target,progress=>{const row=$('#up-'+i);if(row){row.querySelector('.progress span').style.width=progress+'%';row.querySelector('.upload-status').textContent=progress===100?'Saving file…':progress+'% uploaded'}});uploaded.push({id:saved.id,name:f.name});const row=$('#up-'+i);if(row){row.querySelector('.progress span').style.width='100%';row.querySelector('.upload-status').textContent='Saved'}added++;}catch(err){const row=$('#up-'+i);if(row){row.querySelector('.upload-status').textContent=err.message;row.querySelector('.upload-status').style.color='#b43c50';row.querySelector('.progress span').style.background='#d57987'}}}uploading=false;try{await syncWorkspace()}catch(error){toast(error.message)}if($('#modal').open&&$('#upload-list')){$('#modal-title').textContent='Upload complete';$('#upload-list').insertAdjacentHTML('beforeend',uploaded.map(f=>`<button type="button" class="btn upload-notify" data-action="notify-file:${f.id}">${icon('inbox')}Notify someone: ${esc(f.name)}</button>`).join(''));}toast(`${added} of ${picked.length} files saved${added<picked.length?' · Some files could not be added':''}`);})();}
