boot();

async function showDevices(){const {devices}=await api('/devices');openModal('Desktop sync',`<p>Connect IHS Sync on your Mac or Windows PC to keep selected folders available offline. Each computer uses its own connection key.</p><div style="margin-top:15px">${devices.filter(d=>!d.revoked).map(d=>`<div class="sharing-row"><div><strong>${esc(d.name)}</strong><small>Expires ${isoDate(d.expires)}</small></div><button type="button" class="btn" data-action="revoke-device:${d.id}">Disconnect</button></div>`).join('')||'<div class="notice">No computers connected yet.</div>'}</div>`, '<button type="button" class="btn" data-action="close">Close</button><button type="button" class="btn primary" data-action="new-device">Connect a computer</button>');}
function newDevice(){openModal('Connect a computer','<label class="field">Computer name<input name="name" required maxlength="80" placeholder="e.g. Office Windows PC"></label><p>The connection lasts 90 days and follows your current folder permissions. Disconnecting stops future syncing; it cannot erase files already downloaded.</p>',modalButtons('Create connection key'),async data=>{const result=await api('/devices',{method:'POST',body:{name:data.get('name')}});openModal('Your connection key',`<div class="notice">Paste this key into IHS Sync on your computer. It is shown only once.</div><label class="field">Connection key<input readonly value="${esc(result.token)}" autocomplete="off" spellcheck="false"></label><p>Server address: <strong>${esc(location.origin)}</strong></p>`);});}
function revokeDevice(id){openModal('Disconnect this computer?','<p>It will stop syncing. Files already downloaded remain on the computer.</p>',modalButtons('Disconnect',true),async()=>{await api('/devices/'+id,{method:'DELETE'});await showDevices();toast('Computer disconnected');});}

// Dates are shown as YYYY-MM-DD (ISO 8601); date-times add HH:MM in Irish time.
const irishParts=v=>Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Dublin',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(v)).map(p=>[p.type,p.value]));
const isoDate=v=>{if(!v)return '';if(/^\d{4}-\d{2}-\d{2}$/.test(v))return v;const p=irishParts(v);return `${p.year}-${p.month}-${p.day}`};
const isoDateTime=v=>{if(!v)return '';const p=irishParts(v);return `${p.year}-${p.month}-${p.day} ${p.hour}:${p.minute}`};
const diaryToday=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Dublin',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
let diaryMonth=diaryToday.slice(0,7),diaryDay=diaryToday,diaryBookings=[];
const diaryDate=d=>new Date(d+'T12:00:00Z');
const shiftDay=(d,n)=>{const v=diaryDate(d);v.setUTCDate(v.getUTCDate()+n);return v.toISOString().slice(0,10)};
const diaryLabel=d=>`${d} · ${diaryDate(d).toLocaleDateString('en-IE',{timeZone:'UTC',weekday:'long'})}`;
const dayBookings=d=>diaryBookings.filter(b=>b.start<shiftDay(d,1)+'T00:00'&&b.end>d+'T00:00');
async function loadCalendar(){await loadGroups();const year=Number(diaryMonth.slice(0,4));const data=await api('/calendar?from='+year+'-01-01T00:00&to='+(year+1)+'-01-01T00:00');diaryBookings=data.bookings;}
function renderYearBookings(){const year=diaryMonth.slice(0,4);let month='';const rows=diaryBookings.map(b=>{const group=b.start.slice(0,4)<year?year+'-01':b.start.slice(0,7);const heading=group!==month?`<li class="diary-year-group"><h3 class="diary-year-month">${diaryDate(group+'-01').toLocaleDateString('en-IE',{timeZone:'UTC',month:'long'})}</h3></li>`:'';month=group;return `${heading}<li><button class="diary-year-entry" data-action="cal-edit:${b.id}"><strong>${esc(b.title)}</strong><span>${esc(bookingRange(b))}</span><small>${esc(b.ownerName)} · ${b.visibility==='private'?'Private':b.visibility==='groups'?'Group':'Public'}</small></button></li>`;}).join('');return `<section class="diary-year" aria-labelledby="diary-year-title"><div class="diary-year-header"><div class="eyebrow">Year at a glance</div><h2 id="diary-year-title">${year} bookings</h2><p>${diaryBookings.length} booking${diaryBookings.length===1?'':'s'} · In date order</p></div><div class="diary-year-scroll" tabindex="0" role="region" aria-label="Bookings for ${year}">${rows?`<ul class="diary-year-list">${rows}</ul>`:'<p class="diary-empty">No bookings for this year yet.</p>'}</div></section>`;}

function bookingRange(b){return b.allDay?`${b.start.slice(0,10)} → ${shiftDay(b.end.slice(0,10),-1)} · All day`:`${b.start.replace('T',' ')} → ${b.end.replace('T',' ')}`;}
function renderCalendar(){const first=diaryMonth+'-01',offset=(diaryDate(first).getUTCDay()+6)%7,count=new Date(Date.UTC(Number(diaryMonth.slice(0,4)),Number(diaryMonth.slice(5)),0)).getUTCDate();return `<div class="page-heading"><div><div class="eyebrow">Plan your time</div><h1 tabindex="-1">Calendar diary</h1><p>Ireland time (Europe/Dublin)</p></div><div class="actions">${btn('Refresh','cal-refresh','calendar')}${btn('Book time','cal-new','plus',true)}</div></div><div class="diary-layout"><section class="diary-calendar"><div class="diary-toolbar"><h2>${diaryMonth}</h2><div class="actions"><button class="btn" data-action="cal-prev" aria-label="Previous month">‹</button><button class="btn" data-action="cal-today">Today</button><button class="btn" data-action="cal-next" aria-label="Next month">›</button></div></div><div class="diary-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="diary-weekday">${d}</div>`).join('')}${Array.from({length:offset},()=>'<div class="diary-blank"></div>').join('')}${Array.from({length:count},(_,i)=>{const d=diaryMonth+'-'+String(i+1).padStart(2,'0'),entries=dayBookings(d);return `<button class="diary-day ${d===diaryDay?'selected':''} ${d===diaryToday?'today':''}" data-action="cal-day:${d}" aria-pressed="${d===diaryDay}" aria-label="${esc(diaryLabel(d))}, ${entries.length} bookings"><span class="diary-number">${i+1}</span>${entries.slice(0,2).map(b=>`<span class="diary-chip">${esc(b.title)}</span>`).join('')}${entries.length>2?`<small>+${entries.length-2} more</small>`:''}</button>`}).join('')}</div><p class="diary-hint">Select a date to open a new booking. </p></section><aside class="diary-side">${renderYearBookings()}</aside></div>`;}
async function calendarAction(action,id){if(!signedIn)return;if(action==='cal-refresh'){await loadCalendar();render();return;}if(action==='cal-new')return bookingForm();if(action==='cal-edit')return bookingForm(diaryBookings.find(b=>b.id===id));if(action==='cal-delete'){const b=diaryBookings.find(b=>b.id===id);return openModal('Delete booking?',`<p>Remove <strong>${esc(b.title)}</strong> and make this period available again?</p>`,modalButtons('Delete booking',true),async()=>{await api('/calendar/'+b.id,{method:'DELETE',body:{revision:b.revision}});$('#modal').close();await loadCalendar();render();toast('Booking deleted');});}if(action==='cal-day'){diaryDay=id;render();return bookingForm();}else{if(action==='cal-today'){diaryMonth=diaryToday.slice(0,7);diaryDay=diaryToday;}else{const d=diaryDate(diaryMonth+'-01');d.setUTCMonth(d.getUTCMonth()+(action==='cal-prev'?-1:1));if(d.getUTCFullYear()<2000||d.getUTCFullYear()>2098)return;diaryMonth=d.toISOString().slice(0,7);diaryDay=diaryMonth+'-01';}await loadCalendar();}render();}
function bookingForm(b){if(b&&b.owner!==currentUser&&user().role!=='Super User'){openModal('Booking details',`<h3>${esc(b.title)}</h3><p>${esc(bookingRange(b))} · Ireland time</p><p>Booked by ${esc(b.ownerName)}</p><p style="white-space:pre-wrap">${esc(b.notes)}</p><div class="notice">Only its owner or a Super User can change this booking.</div>`);return;}
const all=b?.allDay||false,start=b?.start||diaryDay+'T09:00',end=b?.end||diaryDay+'T10:00';openModal(b?'Edit booking':'Book time',`<p>Ireland time</p><label class="field">Title<input name="title" required maxlength="160" value="${esc(b?.title||'')}" placeholder="Appointment, leave, team meeting…"></label><label class="check-label"><input id="diary-all-day" name="allDay" type="checkbox" ${all?'checked':''}>All day / multiple days</label><div class="diary-fields"><label class="field">Start<input id="diary-start" name="start" type="${all?'date':'datetime-local'}" required value="${all?start.slice(0,10):start}"></label><label class="field"><span id="diary-end-label">${all?'Last day (included)':'End'}</span><input id="diary-end" name="end" type="${all?'date':'datetime-local'}" required value="${all?shiftDay(end.slice(0,10),-1):end}"></label></div><label class="field">Visibility<select id="booking-visibility" name="visibility" aria-label="Visibility">${[['public','Public — all IHS Cloud users'],['private','Private — creator only'],['groups','User groups']].map(([v,label])=>`<option value="${v}" ${(b?.visibility||'public')===v?'selected':''}>${label}</option>`).join('')}</select></label><fieldset id="booking-groups" ${(b?.visibility)!=='groups'?'hidden':''}><legend>User groups</legend>${userGroups.map(g=>`<label class="check-label"><input type="checkbox" name="groupIds" value="${g.id}" ${b?.groupIds?.includes(g.id)?'checked':''}>${esc(g.name)}</label>`).join('')||'<p>No groups available. Ask a Super User to create one.</p>'}</fieldset><label class="field">Diary notes<textarea name="notes" rows="4" maxlength="4000" placeholder="Details for your team">${esc(b?.notes||'')}</textarea></label>`,`${b?`<button type="button" class="btn danger" data-action="cal-delete:${b.id}">Delete</button>`:''}${modalButtons('Save booking')}`,async data=>{const allDay=data.get('allDay')==='on';const start=data.get('start')+(allDay?'T00:00':'');let end=data.get('end');if(allDay)end=shiftDay(end,1)+'T00:00';await api('/calendar'+(b?'/'+b.id:''),{method:b?'PUT':'POST',body:{title:data.get('title'),notes:data.get('notes'),start,end,allDay,visibility:data.get('visibility'),groupIds:data.getAll('groupIds'),...(b?{revision:b.revision}:{})}});diaryMonth=start.slice(0,7);diaryDay=start.slice(0,10);$('#modal').close();await loadCalendar();render();toast('Booking saved');});
$('#booking-visibility').onchange=e=>{$('#booking-groups').hidden=e.target.value!=='groups';};
$('#diary-all-day').onchange=e=>{for(const [selector,time]of [['#diary-start','09:00'],['#diary-end','10:00']]){const input=$(selector),v=input.value.slice(0,10)||diaryDay;input.type=e.target.checked?'date':'datetime-local';input.value=v+(e.target.checked?'':'T'+time);}$('#diary-end-label').textContent=e.target.checked?'Last day (included)':'End';};}

let userGroups=[];
async function loadGroups(){userGroups=(await api('/groups')).groups;}
function renderGroups(){return `<div class="page-heading"><h1>User groups</h1>${btn('New group','group-new','plus',true)}</div><div class="group-list">${userGroups.map(g=>`<article><h2>${esc(g.name)}</h2><p>${g.members?.length||0} members</p>${btn('Edit',`group-edit:${g.id}`,'edit')}</article>`).join('')||'<p>No groups.</p>'}</div>`;}
function groupAction(action,id){if(user().role!=='Super User')return;const g=userGroups.find(g=>g.id===id);if(action==='group-delete')return openModal('Delete group?',`<p>${esc(g.name)}</p>`,modalButtons('Delete group',true),async()=>{await api('/groups/'+id,{method:'DELETE',body:{}});$('#modal').close();await loadGroups();render();});openModal(g?'Edit group':'New group',`<label class="field">Group name<input name="name" required maxlength="80" value="${esc(g?.name||'')}"></label><fieldset><legend>Members</legend>${users.filter(u=>u.active).map(u=>`<label class="check-label"><input name="members" value="${u.id}" type="checkbox" ${g?.members?.includes(u.id)?'checked':''}>${esc(u.name)}</label>`).join('')}</fieldset>`,`${g?btn('Delete',`group-delete:${g.id}`,'trash'):''}${modalButtons('Save group')}`,async data=>{await api('/groups'+(g?'/'+g.id:''),{method:g?'PUT':'POST',body:{name:data.get('name'),members:data.getAll('members')}});$('#modal').close();await loadGroups();render();toast('Group saved');});}

let boardNotes=[],inboxItems=[],inboxUnread=0,inboxHasMore=false;
const updateTime=n=>isoDateTime(n);
async function loadBoard(){boardNotes=(await api('/board')).notes;}
async function loadInbox(append=false){const result=await api('/inbox?offset='+(append?inboxItems.length:0));inboxItems=append?[...inboxItems,...result.items]:result.items;inboxUnread=result.unread;inboxHasMore=result.hasMore;}
function renderBoard(){return `<div class="page-heading"><div><h1>Message Board</h1><p>Team notes</p></div><div class="actions">${btn('Refresh','board-refresh','calendar')}${btn('Add note','board-new','plus',true)}</div></div><section class="sticky-board" aria-label="Team message board">${boardNotes.map(n=>`<article class="sticky-note sticky-${n.color}"><div class="note-top"><span>${n.pinned?'Pinned':'Team note'}</span>${n.owner===currentUser||user().role==='Super User'?`<button class="icon-button" data-action="board-edit:${n.id}" aria-label="Edit ${esc(n.title)}">${icon('edit')}</button>`:''}</div><h2>${esc(n.title)}</h2><p class="note-message">${esc(n.message)}</p><footer><strong>${esc(n.ownerName)}</strong><time>${updateTime(n.modified)}</time></footer></article>`).join('')||'<div class="empty"><h3>No notes yet</h3><p>Add a note for your team.</p></div>'}</section>`;}
async function boardAction(action,id){if(action==='board-refresh'){await loadBoard();render();return;}const n=boardNotes.find(n=>n.id===id);if(action==='board-delete'){openModal('Remove note?',`<p>${esc(n.title)}</p>`,modalButtons('Remove note',true),async()=>{await api('/board/'+id,{method:'DELETE',body:{revision:n.revision}});$('#modal').close();await loadBoard();render();});return;}openModal(n?'Edit note':'Add note',`<label class="field">Title<input name="title" required maxlength="120" value="${esc(n?.title||'')}"></label><label class="field">Message<textarea name="message" required maxlength="2000" rows="6">${esc(n?.message||'')}</textarea></label><label class="field">Colour<select name="color" aria-label="Note colour">${[['yellow','Sunshine'],['mint','Mint'],['blue','Sky'],['pink','Rose']].map(([v,label])=>`<option value="${v}" ${(n?.color||'yellow')===v?'selected':''}>${label}</option>`).join('')}</select></label><label class="check-label"><input name="pinned" type="checkbox" ${n?.pinned?'checked':''}>Pin to the top</label><p>Visible to all signed-in IHS Cloud users.</p>`,`${n?btn('Remove',`board-delete:${n.id}`,'trash'):''}${modalButtons(n?'Save note':'Post note')}`,async data=>{await api('/board'+(n?'/'+n.id:''),{method:n?'PUT':'POST',body:{title:data.get('title'),message:data.get('message'),color:data.get('color'),pinned:data.get('pinned')==='on',...(n?{revision:n.revision}:{})}});$('#modal').close();await loadBoard();render();toast('Note saved');});}
function renderInbox(){return `<div class="page-heading"><div><h1>${icon('inbox')} In-tray</h1><p>${inboxUnread} unread</p></div>${btn('Refresh','inbox-refresh','calendar')}</div><section class="inbox-list" aria-label="File notifications">${inboxItems.map(i=>`<article class="inbox-item ${i.read?'':'unread'}"><div class="inbox-symbol">${icon('inbox')}</div><div class="inbox-body"><div class="inbox-meta"><strong>${esc(i.senderName)}</strong><time>${updateTime(i.created)}</time>${i.read?'':'<span class="pill">New</span>'}</div><h2>${esc(i.file?.name||'File unavailable')}</h2>${i.available?`<p class="inbox-path">${icon('folder')}${esc(i.file.path)}</p>${i.message?`<p class="inbox-message">${esc(i.message)}</p>`:''}<div class="actions">${btn(i.file.reference?'View reference':'Open file',`inbox-open:${i.id}`,'files',true)}${btn('Open folder',`inbox-folder:${i.id}`,'folder')}</div>`:'<p>This file was removed or your access changed.</p>'}</div><button class="btn inbox-read" data-action="inbox-read:${i.id}">${i.read?'Mark unread':'Mark read'}</button></article>`).join('')||`<div class="empty">${icon('inbox')}<h3>Your In-tray is empty</h3><p>File notifications sent to you will appear here.</p></div>`}${inboxHasMore?btn('Load older notifications','inbox-more','down'):''}</section>`;}
async function inboxAction(action,id){if(action==='inbox-more'){await loadInbox(true);render();return;}if(action==='inbox-refresh'){await loadInbox();render();return;}const i=inboxItems.find(i=>i.id===id);if(!i)return;if(action==='inbox-read'){await api('/inbox/'+id,{method:'PATCH',body:{read:!i.read}});await loadInbox();render();return;}await syncWorkspace();const {item:fresh}=await api('/inbox/'+id);if(!fresh?.available){page='inbox';render();toast('File access is unavailable');return;}await api('/inbox/'+id,{method:'PATCH',body:{read:true}});await loadInbox();if(action==='inbox-folder'){page='files';workspaceTab='folders';currentFolder=fresh.file.folder;query='';render();}else{page='inbox';render();fileDetails(fresh.file.id);}}
async function notifyFile(id){const f=files.find(f=>f.id===id);if(!f)return toast('Refresh the files list first.');const data=await api('/files/'+id+'/recipients');openModal('Send to In-tray',`<div class="notice"><strong>${esc(f.name)}</strong><br>${esc(data.path)}</div><fieldset><legend>Recipients with file access</legend>${data.recipients.map(u=>`<label class="check-label"><input name="recipients" type="checkbox" value="${u.id}">${esc(u.name)}</label>`).join('')||'<p>No other users have access. Update the folder permissions first.</p>'}</fieldset><label class="field">Message (optional)<textarea name="message" maxlength="1000" rows="3" placeholder="A quick note about this file"></textarea></label>`,data.recipients.length?modalButtons('Send notification'):'',async form=>{const recipients=form.getAll('recipients');if(!recipients.length)throw Error('Choose at least one recipient.');await api('/inbox',{method:'POST',body:{fileId:id,recipients,message:form.get('message')}});$('#modal').close();toast('Sent to In-tray');});}
setInterval(async()=>{if(!signedIn||document.hidden)return;const who=currentUser;try{const data=await api('/inbox/count');if(signedIn&&currentUser===who){inboxUnread=data.unread;const el=$('.inbox-count');if(el){el.textContent=inboxUnread;el.hidden=!inboxUnread;}}}catch{}},30000);

function addLocation(){openModal('Add file location',`<label class="field">Location<select name="source"><option value="host" selected>Host storage (default)</option><option value="occ">IHS Sync folder</option><option value="existing">Existing file</option></select></label>`,modalButtons('Continue'),data=>{const source=data.get('source');$('#modal').close();if(source==='host')chooseUpload();else referenceForm(null,source);});}
function referenceForm(f=null,source='existing'){const options=folders.filter(x=>can(x.id,f?'manage':'upload'));if(!options.length)return toast('No writable folders available.');openModal(f?'Edit file reference':'Add file reference',`<label class="field">Name<input name="name" required maxlength="160" value="${esc(f?.name||'')}" placeholder="e.g. Service manual.pdf"></label><label class="field">IHS Cloud folder<select name="folder">${options.map(x=>`<option value="${x.id}" ${x.id===(f?.folder||currentFolder)?'selected':''}>${esc(folderPath(x.id))}</option>`).join('')}</select></label><label class="field">Location<select name="source"><option value="occ" ${(f?.source||source)==='occ'?'selected':''}>IHS Sync folder</option><option value="existing" ${(f?.source||source)==='existing'?'selected':''}>Existing file</option></select></label><label class="field">File or folder path<input name="path" required maxlength="2048" value="${esc(f?.path||'')}" placeholder="Absolute local, mapped-drive or network-share path" spellcheck="false"></label><p class="muted">Reference only. The file stays on its drive. People need access to that drive to open it.</p>`,modalButtons('Save reference'),async data=>{await api('/references'+(f?'/'+f.id:''),{method:f?'PUT':'POST',body:{...Object.fromEntries(data),...(f?{modified:f.modified}:{})}});$('#modal').close();await syncWorkspace();toast('Reference saved');});}
function referenceDetails(f){if(!can(f.folder,'view'))return toast('Access unavailable.');openModal(f.name,`<dl class="details"><dt>Location</dt><dd>${f.source==='occ'?'IHS Sync folder':'Existing file'}</dd><dt>Drive path</dt><dd><input class="reference-path" aria-label="Drive path" readonly value="${esc(f.path)}"></dd><dt>IHS Cloud folder</dt><dd>${esc(folderPath(f.folder))}</dd></dl><p class="muted">Copy the path into Finder or File Explorer on a computer with access to this drive. This reference does not copy or sync the file.</p>${can(f.folder,'manage')?`<div class="actions">${btn('Edit reference',`edit-reference:${f.id}`,'edit')}${btn('Remove reference',`delete-reference:${f.id}`,'trash')}</div>`:''}`,`${btn('Close','close','close')}${btn('Copy path',`copy-path:${f.id}`,'files',true)}${btn('Notify someone',`notify-file:${f.id}`,'inbox')}`);}
function deleteReference(id){const f=files.find(f=>f.id===id);openModal('Remove reference?',`<p>${esc(f.name)}</p><p>The original file stays on its drive.</p>`,modalButtons('Remove reference',true),async()=>{await api('/references/'+id,{method:'DELETE',body:{modified:f.modified}});$('#modal').close();await syncWorkspace();toast('Reference removed');});}
